python
def bitRibbonsPeakTicket(readings):
    a=readings
    out=[]
    for x in a:
        count=0
        while x:
            x&=x-1
            count+=1
        out.append(count)
    return max(out,default=0)


java
class Solution {
  public int bitRibbonsPeakTicket(int[] readings) {
    int[] a=readings; List<Integer> out=new ArrayList<>();
    {for(int x:a){int count=0;while(x!=0){x&=x-1;count++;}out.add(count);}}
    int answer=out.isEmpty()?0:out.get(0);for(int x:out)answer=Math.max(answer,x);return answer;
  }
}
